    double minor[2][2];
    int mi = 0;
    for (int i = 0; i < 3; i++) {
        if (i == row) continue;
        int mj = 0;
        for (int j = 0; j < 3; j++) {
            if (j == col) continue;
            minor[mi][mj] = m[i][j];
            mj++;
        }
        mi++;
    }

    // Calculate determinant of the 2x2 minor matrix
    double det = minor[0][0] * minor[1][1] - minor[0][1] * minor[1][0];

    // Apply sign factor: (-1)^(row+col)
    double sign = ((row + col) % 2 == 0) ? 1.0 : -1.0;

    return sign * det;

